(function () {
  // ── shared helpers (SVG, tweening) ─────────────────────────────────────────
  var NS = "http://www.w3.org/2000/svg";
  var svg = document.getElementById("scene");
  var labelEl = document.getElementById("step-label");
  var captionEl = document.getElementById("caption");

  function el(name, attrs, parent) {
    var node = document.createElementNS(NS, name);
    for (var key in attrs) node.setAttribute(key, attrs[key]);
    if (parent) parent.appendChild(node);
    return node;
  }
  function txt(parent, x, y, cls, str, anchor) {
    var t = el("text", { x: x, y: y, class: cls }, parent);
    if (anchor) t.setAttribute("text-anchor", anchor);
    t.textContent = str;
    return t;
  }
  function show(node, on) {
    node.setAttribute("opacity", on ? "1" : "0");
  }
  function place(node, x, y) {
    node.style.transform = "translate(" + x + "px," + y + "px)";
  }
  function setLine(node, x1, y1, x2, y2) {
    node.setAttribute("x1", x1);
    node.setAttribute("y1", y1);
    node.setAttribute("x2", x2);
    node.setAttribute("y2", y2);
  }
  function lerp(a, b, e) {
    return a + (b - a) * e;
  }
  function round1(v) {
    return (Math.round(v * 10) / 10).toFixed(1);
  }

  // Eased animation. fn(e) is called with e from 0 to 1. Without
  // requestAnimationFrame (or with ms = 0) it jumps straight to fn(1).
  var animTokens = {};
  function anim(key, ms, fn) {
    var token = (animTokens[key] || 0) + 1;
    animTokens[key] = token;
    if (typeof requestAnimationFrame !== "function" || ms <= 0) {
      fn(1);
      return;
    }
    var start = null;
    function frame(now) {
      if (animTokens[key] !== token) return;
      if (start === null) start = now;
      var p = Math.min(1, (now - start) / ms);
      var e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
      fn(e);
      if (p < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  // Arrowheads, one marker per colour.
  var COLORS = { g: "#1DB584", y: "#E2B44A", p: "#F472B6", b: "#38BDF8", w: "#c9dccf", r: "#F87171" };
  var defs = el("defs", {}, svg);
  Object.keys(COLORS).forEach(function (k) {
    var m = el("marker", { id: "ah-" + k, viewBox: "0 0 10 10", refX: 9, refY: 5, markerUnits: "userSpaceOnUse", markerWidth: 13, markerHeight: 13, orient: "auto" }, defs);
    el("path", { d: "M0 0 L10 5 L0 10 Z", fill: COLORS[k] }, m);
  });
  function arrow(parent, colorKey, width) {
    return el("line", { x1: 0, y1: 0, x2: 0, y2: 0, stroke: COLORS[colorKey], "stroke-width": width || 3, "marker-end": "url(#ah-" + colorKey + ")", "stroke-linecap": "round" }, parent);
  }
  function polygon(parent, cls) {
    return el("polygon", { points: "", class: cls }, parent);
  }
  function setPoly(node, pts) {
    node.setAttribute("points", pts.map(function (p) { return p[0].toFixed(1) + "," + p[1].toFixed(1); }).join(" "));
  }
  function lerpPts(a, b, e) {
    return a.map(function (p, i) { return [lerp(p[0], b[i][0], e), lerp(p[1], b[i][1], e)]; });
  }
  // Maps maths coordinates (x right, y up) to screen pixels.
  function makePlane(cx, cy, s) {
    return {
      x: function (v) { return cx + s * v; },
      y: function (v) { return cy - s * v; },
      pt: function (p) { return [cx + s * p[0], cy - s * p[1]]; },
      s: s, cx: cx, cy: cy
    };
  }
  function axes(parent, plane, xr, yr) {
    el("line", { x1: plane.x(-xr), y1: plane.y(0), x2: plane.x(xr), y2: plane.y(0), class: "axis" }, parent);
    el("line", { x1: plane.x(0), y1: plane.y(-yr), x2: plane.x(0), y2: plane.y(yr), class: "axis" }, parent);
  }

  // ── Module 3 helpers: graphs, curves, contour plane ───────────────────────
  // makeGraph maps maths values to pixels with separate x and y scales.
  function makeGraph(ox, oy, sx, sy) {
    return {
      ox: ox, oy: oy, sx: sx, sy: sy,
      x: function (v) { return ox + sx * v; },
      y: function (v) { return oy - sy * v; }
    };
  }
  function curveD(g, f, a, b, n) {
    var d = "";
    for (var i = 0; i <= n; i++) {
      var v = a + ((b - a) * i) / n;
      d += (i ? " L " : "M ") + g.x(v).toFixed(1) + " " + g.y(f(v)).toFixed(1);
    }
    return d;
  }
  function setD(node, d) {
    node.setAttribute("d", d);
  }
  function fmt(v, n) {
    return (Math.round(v * 100000) / 100000).toFixed(n === undefined ? 1 : n);
  }
  function drawAxes(parent, g, xmax, ymax, xticks, yticks) {
    el("line", { x1: g.x(0), y1: g.y(0), x2: g.x(xmax), y2: g.y(0), class: "axis" }, parent);
    el("line", { x1: g.x(0), y1: g.y(0), x2: g.x(0), y2: g.y(ymax), class: "axis" }, parent);
    (xticks || []).forEach(function (t) { txt(parent, g.x(t), g.y(0) + 15, "tick", String(t), "middle"); });
    (yticks || []).forEach(function (t) { txt(parent, g.x(0) - 7, g.y(t) + 4, "tick", String(t), "end"); });
  }
  function card(parent, x, y, w, h, cls) {
    return el("rect", { x: x, y: y, width: w, height: h, rx: 10, class: cls || "fillG" }, parent);
  }
  function ring(parent, cx, cy, rx, ry, cls) {
    return el("ellipse", { cx: cx, cy: cy, rx: rx, ry: ry, fill: "none", class: cls || "contour" }, parent);
  }
  function clipTo(id, x, y, w, h) {
    var c = el("clipPath", { id: id }, defs);
    el("rect", { x: x, y: y, width: w, height: h }, c);
  }

  var EXPLAIN = {"model-parameters":{"h":"WHAT YOU ARE LOOKING AT","t":"The model is **prediction = w × x**. The input is **x = 2** and the true answer is **y = 6**, so the best weight is 3. We start at **w = 0**."},"make-prediction":{"h":"MAKE A PREDICTION","t":"With w = 0 the model predicts **0 × 2 = 0**. The true answer is 6, so the prediction is **far off**."},"compute-loss":{"h":"MEASURE THE MISS WITH THE LOSS","t":"**Loss = (prediction − y)² = (0 − 6)² = 36.** The graph shows the loss for every possible weight. We are standing **high on the left** of the bowl."},"parameter-change":{"h":"CHANGE THE WEIGHT, WATCH THE LOSS","t":"Nudge w and the prediction changes, and so does the loss. **The loss is a function of the weight**, and we want the weight with the smallest loss."},"gradient":{"h":"THE GRADIENT SAYS HOW THE LOSS REACTS","t":"The slope of the loss with respect to w is **2 × (prediction − y) × x = 2 × (−6) × 2 = −24.** Negative: raising w lowers the loss. Large: the ground is steep here."},"downhill-direction":{"h":"GO AGAINST THE SLOPE'S SIGN","t":"A **negative gradient** means downhill is to the right, so **w should go up**. The rule: **step against the gradient**."},"update":{"h":"UPDATE THE WEIGHT","t":"**w ← w − η × gradient**, with learning rate η = 0.05: new w = 0 − 0.05 × (−24) = **1.2**. The prediction is now 2.4 and the loss has fallen from **36 to 12.96**."},"repeat":{"h":"REPEAT WITH THE NEW GRADIENT","t":"Recompute the gradient at the new weight (**−14.4**) and step again: **w goes 1.2 → 1.92 → 2.35 …** The gradients shrink as the ground flattens, so the steps shrink too."},"learning-connection":{"h":"TAKEAWAY","t":"**Predict, measure the loss, compute the gradient, update the weights, and repeat.** Training a large model is this same loop with millions of weights."}};
  // ── scene ──
  var steps = [
    { id: "model-parameters", label: "A tiny model with one weight", caption: "The model is prediction = w × x. The input is x = 2, and the true answer is y = 6, so the best weight is 3. We start at w = 0." },
    { id: "make-prediction", label: "Make a prediction", caption: "With w = 0 the model predicts 0 × 2 = 0. The true answer is 6, so the prediction is far off." },
    { id: "compute-loss", label: "Measure the miss with the loss", caption: "Loss = (prediction − y)² = (0 − 6)² = 36. The graph shows the loss for every possible weight. We are standing high on the left of the bowl." },
    { id: "parameter-change", label: "Change the weight, watch the loss", caption: "Nudge w and the prediction changes, and so does the loss. The loss is a function of the weight. We want to find the weight with the smallest loss." },
    { id: "gradient", label: "The gradient says how the loss reacts", caption: "The slope of the loss with respect to w is 2 × (prediction − y) × x = 2 × (−6) × 2 = −24. Negative: raising w lowers the loss. Large: the ground is steep here." },
    { id: "downhill-direction", label: "Go the opposite way of the slope's sign", caption: "A negative gradient means downhill is to the right. So w should go up. Rule: step against the gradient." },
    { id: "update", label: "Update the weight", caption: "w ← w − η × gradient, with learning rate η = 0.05. New w = 0 − 0.05 × (−24) = 1.2. The prediction is now 2.4 and the loss has fallen from 36 to 12.96." },
    { id: "repeat", label: "Repeat with the new gradient", caption: "Recompute the gradient at the new weight (−14.4) and step again. w goes 1.2 → 1.92 → 2.35 … The gradients shrink as the ground flattens, so the steps shrink too." },
    { id: "learning-connection", label: "This loop is how models learn", caption: "Predict, measure the loss, compute the gradient, update the weights, and repeat. Training a large model is this same loop with millions of weights." }
  ];

  var X = 2, Y = 6, ETA = 0.05;
  function L(w) { return (w * X - Y) * (w * X - Y); }
  function grad(w) { return 2 * (w * X - Y) * X; }
  var ws = [0];
  for (var s = 0; s < 6; s++) ws.push(ws[ws.length - 1] - ETA * grad(ws[ws.length - 1]));

  // Pipeline across the top.
  var pipe = el("g", {}, svg);
  card(pipe, 14, 14, 100, 70, "fillA");
  txt(pipe, 64, 36, "note", "input x", "middle");
  txt(pipe, 64, 68, "big", "2", "middle");
  txt(pipe, 136, 56, "big", "×", "middle");
  var wBox = card(pipe, 158, 14, 110, 70, "fillG");
  txt(pipe, 213, 36, "note", "weight w", "middle");
  var wTxt = txt(pipe, 213, 68, "big", "0.0", "middle");
  var a1 = arrow(pipe, "w", 3); setLine(a1, 270, 49, 306, 49);
  card(pipe, 308, 14, 130, 70, "fillB");
  txt(pipe, 373, 36, "note", "prediction = w × x", "middle");
  var predTxt = txt(pipe, 373, 68, "big", "?", "middle");
  var a2 = arrow(pipe, "w", 3); setLine(a2, 440, 49, 476, 49);
  card(pipe, 478, 14, 148, 70, "fillA");
  txt(pipe, 552, 36, "note", "loss = (prediction − 6)²", "middle");
  var lossTxt = txt(pipe, 552, 68, "big", "?", "middle");
  var target = txt(pipe, 552, 100, "lbl lbl-y", "true answer y = 6", "middle");

  var goal = el("g", {}, svg);
  card(goal, 60, 170, 520, 120, "fillG");
  txt(goal, 320, 204, "lbl", "The goal of training", "middle");
  txt(goal, 320, 232, "note", "find the weight w that makes the loss as small as possible.", "middle");
  txt(goal, 320, 258, "note", "Here we can see the answer is w = 3, but a real model has to FIND it.", "middle");

  // Loss graph (bottom left).
  var g = makeGraph(52, 336, 75, 5.2);
  var gr = el("g", {}, svg);
  drawAxes(gr, g, 4.2, 38, [0, 1, 2, 3, 4], [0, 12, 24, 36]);
  txt(gr, g.x(4.2) + 8, g.y(0) + 4, "note", "weight w", "start");
  txt(gr, g.x(0) + 8, g.y(38) + 4, "note", "loss", "start");
  el("path", { class: "curve", d: curveD(g, L, 0, 4, 60) }, gr);
  var tan = el("line", { stroke: "#1db584", "stroke-width": 3, "stroke-linecap": "round" }, svg);
  setLine(tan, g.x(-0.1), g.y(36 + 24 * 0.1), g.x(0.7), g.y(36 - 24 * 0.7));
  var tanLbl = txt(svg, g.x(0.75), g.y(36 - 24 * 0.7) + 2, "lbl lbl-g", "slope −24", "start");
  var dirArrow = arrow(svg, "g", 5);
  setLine(dirArrow, g.x(0) + 14, g.y(36) - 22, g.x(1.1), g.y(36) - 22);
  var dirLbl = txt(svg, g.x(0.6), g.y(36) - 32, "lbl lbl-g", "w should go UP", "middle");
  var trail = el("g", {}, svg);
  var trailDots = ws.map(function (w, i) { return el("circle", { cx: g.x(w), cy: g.y(L(w)), r: 4.5, fill: "#38bdf8", stroke: "#071510", "stroke-width": 1.5 }, trail); });
  var trailLine = el("polyline", { fill: "none", stroke: "#38bdf8", "stroke-width": 2, "stroke-dasharray": "4 3" }, trail);
  trailLine.setAttribute("points", ws.map(function (w) { return g.x(w) + "," + g.y(L(w)); }).join(" "));
  var marker = el("circle", { r: 8, fill: "#e2b44a", stroke: "#071510", "stroke-width": 2 }, svg);

  // Readout panel (bottom right).
  var panel = el("g", {}, svg);
  card(panel, 372, 120, 254, 120, "fillG");
  var p1 = txt(panel, 499, 146, "note", "", "middle");
  var p2 = txt(panel, 499, 174, "mono", "", "middle");
  var p3 = txt(panel, 499, 200, "mono", "", "middle");
  var p4 = txt(panel, 499, 228, "big", "", "middle");

  // Learning loop diagram (final step).
  var loop = el("g", {}, svg);
  ["1  predict", "2  measure the loss", "3  compute the gradient", "4  update the weights"].forEach(function (name, i) {
    var y = 122 + i * 52;
    card(loop, 392, y, 190, 36, i === 3 ? "fillB" : "fillG");
    txt(loop, 487, y + 23, "lbl", name, "middle");
    if (i < 3) { var a = arrow(loop, "w", 3); setLine(a, 487, y + 38, 487, y + 50); }
  });
  var back = el("path", { d: "M 584 296 L 606 296 L 606 140 L 586 140", fill: "none", stroke: "#c9dccf", "stroke-width": 3, "marker-end": "url(#ah-w)" }, loop);
  txt(loop, 624, 220, "note", "repeat", "middle").setAttribute("transform", "rotate(90 624 220)");

  function setW(w, loss) {
    marker.setAttribute("cx", g.x(w)); marker.setAttribute("cy", g.y(L(w)));
    wTxt.textContent = fmt(w, w === Math.round(w) ? 1 : 2);
    predTxt.textContent = fmt(w * X, 2).replace(/\.?0+$/, "") || "0";
    lossTxt.textContent = fmt(L(w), 2).replace(/\.?0+$/, "") || "0";
  }

  function render(index, id) {
    var i = index;
    show(target, i >= 1);
    show(goal, i <= 1);
    show(gr, i >= 2 && i !== 8 || i === 8);
    show(marker, i >= 2);
    show(tan, i === 4); show(tanLbl, i === 4);
    show(dirArrow, i === 5); show(dirLbl, i === 5);
    show(trail, i >= 7);
    show(panel, i >= 3 && i <= 7);
    show(loop, i === 8);
    p1.textContent = ""; p2.textContent = ""; p3.textContent = ""; p4.textContent = "";
    if (i <= 1) { predTxt.textContent = i === 0 ? "?" : "0"; lossTxt.textContent = "?"; wTxt.textContent = "0.0"; }
    if (i >= 2) setW(0);

    if (i === 3) {
      p1.textContent = "loss depends on the weight";
      anim("w", 2400, function (e) { var w = 0.9 * Math.sin(Math.PI * e); setW(w); p3.textContent = "w = " + fmt(w, 2) + "   loss = " + fmt(L(w), 1); });
    } else if (i === 4) {
      p1.textContent = "gradient at w = 0";
      p2.textContent = "2 × (0 − 6) × 2";
      p4.textContent = "= −24";
      p3.textContent = "negative: raise w";
    } else if (i === 5) {
      p1.textContent = "gradient = −24";
      p2.textContent = "against it = +24";
      p3.textContent = "so w moves UP";
    } else if (i === 6) {
      p1.textContent = "w ← w − η × gradient";
      p2.textContent = "= 0 − 0.05 × (−24)";
      p4.textContent = "w = 1.2, loss 12.96";
      anim("w", 1400, function (e) { setW(lerp(0, ws[1], e)); });
    } else if (i === 7) {
      p1.textContent = "w:    0 → 1.2 → 1.92 → 2.35";
      p2.textContent = "loss: 36 → 12.96 → 4.67 → 1.68";
      p3.textContent = "gradient: −24, −14.4, −8.6 …";
      p4.textContent = "w heads to 3";
      anim("w", 3200, function (e) {
        var t = e * (ws.length - 1), j = Math.min(ws.length - 2, Math.floor(t)), f = t - j;
        setW(lerp(ws[j], ws[j + 1], f));
        trailDots.forEach(function (d, k) { d.setAttribute("opacity", k <= t + 0.01 ? "1" : "0"); });
      });
    } else if (i === 8) {
      setW(ws[ws.length - 1]);
    }
  }


  // ── shared runtime: stepping, explanation panel, educational autoplay pacing, bridge ──
  var current = 0;
  var explainHeadEl = document.getElementById("explain-h");

  // **bold** markers in an explanation become <strong> nodes (built with DOM calls, never innerHTML).
  function setRich(node, str) {
    node.textContent = "";
    var parts = String(str).split("**");
    for (var i = 0; i < parts.length; i++) {
      if (parts[i] === "") continue;
      var seg = document.createElement(i % 2 ? "strong" : "span");
      seg.textContent = parts[i];
      node.appendChild(seg);
    }
  }

  function explanationFor(index) {
    var ex = (typeof EXPLAIN === "object" && EXPLAIN) ? EXPLAIN[steps[index].id] : null;
    return ex || { h: "WHAT IS HAPPENING", t: steps[index].caption };
  }

  // Autoplay pace: 4.5 to 10.5 seconds per step, longer for longer explanations, so a learner can read.
  function stepMs(index) {
    var words = String(explanationFor(index).t).replace(/\*\*/g, "").split(/\s+/).length;
    return Math.max(4500, Math.min(10500, Math.round(3800 + words * 165)));
  }

  function renderStep(index) {
    var ex = explanationFor(index);
    labelEl.textContent = steps[index].label;
    if (explainHeadEl) explainHeadEl.textContent = ex.h;
    setRich(captionEl, ex.t);
    render(index, steps[index].id);
  }

  function goTo(index) {
    if (index < 0 || index >= steps.length) return;
    current = index;
    renderStep(current);
    if (window.ReagvisBridge) window.ReagvisBridge.stepChanged(steps[current].id);
  }

  renderStep(current);

  // Autoplay: exactly one timer, one step per tick, stops on the final step.
  // PLAY on the final step restarts from the first step and plays again.
  var timer = null;

  function stopAuto() {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function scheduleNext() {
    timer = setTimeout(function () {
      timer = null;
      if (current >= steps.length - 1) return;
      goTo(current + 1);
      if (current < steps.length - 1) scheduleNext();
    }, stepMs(current));
  }

  function startAuto() {
    if (timer !== null) return;
    if (current >= steps.length - 1) goTo(0);
    scheduleNext();
  }

  window.addEventListener("pagehide", stopAuto);

  window.ReagvisAnimation = {
    stepDuration: stepMs,
    onCommand: function (type, stepId) {
      if (type === "PLAY") startAuto();
      else if (type === "PAUSE") stopAuto();
      else if (type === "NEXT") { stopAuto(); goTo(current + 1); }
      else if (type === "PREVIOUS") { stopAuto(); goTo(current - 1); }
      else if (type === "RESET") { stopAuto(); goTo(0); }
      else if (type === "GOTO_STEP") {
        stopAuto();
        for (var i = 0; i < steps.length; i++) {
          if (steps[i].id === stepId) { goTo(i); break; }
        }
      }
    },
  };

  if (window.ReagvisBridge) {
    window.ReagvisBridge.ready();
    window.ReagvisBridge.stepChanged(steps[current].id);
  }
})();
